const WEEKS = 13;
const DAYS = 7;
const CELL = 12;
const GAP = 3;
const STEP = CELL + GAP;

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
